const waitForEl = async (fn, timeout = 8000, label = 'element') => {
  const start = Date.now();
  while (Date.now() - start < timeout) {
    try { const r = fn(); if (r) return r; } catch (e) {}
    await new Promise(r => setTimeout(r, 150));
  }
  throw new Error(label + ' not found within ' + timeout + 'ms');
};

const dumpView = () => {
  const root = document.querySelector('main') || document.body;
  const desc = (el, d) => {
    if (!el || d > 3) return '';
    const cls = typeof el.className === 'string' && el.className.trim() ? '.' + el.className.trim().split(/\s+/).join('.') : '';
    const s = el.tagName.toLowerCase() + (el.id ? '#' + el.id : '') + cls;
    const kids = Array.from(el.children).slice(0, 8).map(c => desc(c, d + 1)).filter(Boolean);
    return kids.length ? s + '>[' + kids.join(',') + ']' : s;
  };
  return desc(root, 0).slice(0, 500);
};

const ROOT_ID = 'wwa-save-movie';
const clean = s => (s || '').replace(/\s+/g, ' ').trim();

const showFallbackError = (text) => {
  document.getElementById(ROOT_ID)?.remove();
  const host = document.createElement('div');
  host.id = ROOT_ID;
  host.style.cssText = 'position:fixed;bottom:16px;right:16px;z-index:2147483647;';
  const sh = host.attachShadow({ mode: 'open' });
  const box = document.createElement('div');
  box.style.cssText = 'font:13px system-ui,sans-serif;background:#fff;border:1px solid #b00020;color:#b00020;padding:8px 12px;border-radius:6px;box-shadow:0 2px 8px rgba(0,0,0,.2);max-width:320px;';
  box.textContent = 'Save movie widget: ' + text;
  sh.appendChild(box);
  document.body.appendChild(host);
};

try {
  const main = await waitForEl(() => document.querySelector('main[data-movie-id]'), 8000, 'movie detail (main[data-movie-id])');
  const toolbar = await waitForEl(
    () => document.querySelector('[role="toolbar"][aria-label="Movie actions"]') || document.querySelector('.movie-actions'),
    8000,
    'Movie actions toolbar'
  );
  const movieId = clean(main.getAttribute('data-movie-id')) || clean(new URLSearchParams(location.search).get('id'));
  if (!movieId) throw new Error('Could not determine the movie id on this page');

  // Idempotency: replace any previous instance
  document.getElementById(ROOT_ID)?.remove();

  const host = document.createElement('span');
  host.id = ROOT_ID;
  host.style.cssText = 'display:inline-block;vertical-align:middle;margin-left:8px;';
  const shadow = host.attachShadow({ mode: 'open' });
  shadow.innerHTML = '<style>' +
    '.wrap{display:inline-flex;align-items:center;gap:8px;font:14px system-ui,sans-serif}' +
    'button{display:inline-flex;align-items:center;gap:6px;padding:6px 12px;border-radius:6px;border:1px solid #c9a227;background:#fff8e1;color:#5d4500;cursor:pointer;font:inherit}' +
    'button:hover{background:#ffefb3}' +
    'button[aria-pressed="true"]{background:#c9a227;color:#fff}' +
    'button:disabled{opacity:.6;cursor:wait}' +
    '.msg{font-size:12px;color:#666}.msg.err{color:#b00020}' +
    '</style>' +
    '<span class="wrap"><button type="button" aria-pressed="false"><span class="icon">☆</span><span class="label">Save for later</span></button>' +
    '<span class="msg" role="status" aria-live="polite"></span></span>';
  toolbar.appendChild(host);

  const btn = shadow.querySelector('button');
  const icon = shadow.querySelector('.icon');
  const label = shadow.querySelector('.label');
  const msg = shadow.querySelector('.msg');

  let saved = false;
  const render = () => {
    btn.setAttribute('aria-pressed', String(saved));
    icon.textContent = saved ? '★' : '☆';
    label.textContent = saved ? 'Saved' : 'Save for later';
    btn.title = saved ? 'Saved — click to remove from your saved movies' : 'Save this movie to see it later';
  };
  const setMsg = (t, err = false) => { msg.textContent = t; msg.className = 'msg' + (err ? ' err' : ''); };

  // Read movie details from the page (small structured fields only)
  const collect = () => {
    const q = sel => clean(main.querySelector(sel)?.textContent);
    const genresEl = main.querySelector('.genres');
    let genres = genresEl ? Array.from(genresEl.children).map(c => clean(c.textContent)).filter(Boolean) : [];
    if (!genres.length && genresEl) genres = clean(genresEl.textContent).split(/\s*[,·|\/]\s*/).filter(Boolean);
    const yearNum = parseInt(q('.movie-year'), 10);
    const ratingMatch = q('.movie-rating').match(/\d+(\.\d+)?/);
    const ratingNum = ratingMatch ? parseFloat(ratingMatch[0]) : NaN;
    return {
      movieId,
      title: q('.movie-title') || clean(document.title),
      year: Number.isFinite(yearNum) ? yearNum : null,
      runtime: q('.movie-runtime') || null,
      rating: Number.isFinite(ratingNum) ? ratingNum : null,
      genres: genres.slice(0, 10),
      director: q('.movie-director').replace(/^director:\s*/i, '') || null,
      plot: q('.movie-plot').slice(0, 400) || null,
      url: location.href,
      site: location.host,
      savedAt: new Date().toISOString()
    };
  };

  // Initial state
  try {
    const existing = await WidgetAI.db.get('saved_movies', movieId);
    saved = !!existing;
  } catch (e) {
    WidgetAI.log('Could not read saved state: ' + e.message, 'warn');
    setMsg('Could not check saved state', true);
  }
  render();

  btn.addEventListener('click', async () => {
    btn.disabled = true;
    try {
      if (!saved) {
        const data = collect();
        await WidgetAI.db.add('saved_movies', data, movieId);
        const check = await WidgetAI.db.get('saved_movies', movieId);
        if (!check) throw new Error('Save could not be verified');
        saved = true;
        setMsg('Saved "' + data.title + '"');
        WidgetAI.log('Saved "' + data.title + '" to saved_movies');
      } else {
        await WidgetAI.db.remove('saved_movies', movieId);
        const check = await WidgetAI.db.get('saved_movies', movieId);
        if (check) throw new Error('Removal could not be verified');
        saved = false;
        setMsg('Removed from saved movies');
        WidgetAI.log('Removed ' + movieId + ' from saved_movies');
      }
    } catch (e) {
      setMsg('Error: ' + e.message, true);
      WidgetAI.log('Save action failed: ' + e.message, 'error');
    } finally {
      btn.disabled = false;
      render();
    }
  });

  WidgetAI.log('Save button added for movie "' + movieId + '"' + (saved ? ' (already saved)' : ''));
  WidgetAI.status('completed', saved ? 'Movie already saved — button ready' : 'Save button ready');
} catch (err) {
  WidgetAI.log('View evidence: ' + dumpView(), 'warn');
  WidgetAI.log(err.message, 'error');
  try { showFallbackError(err.message); } catch (e) {}
  WidgetAI.status('failed', err.message);
}

const ROOT_ID = 'wwa-saved-movies';

const waitForEl = async (fn, timeout = 8000, label = 'element') => {
  const start = Date.now();
  while (Date.now() - start < timeout) {
    try { const el = fn(); if (el) return el; } catch (e) { /* keep polling */ }
    await new Promise(r => setTimeout(r, 200));
  }
  throw new Error(label + ' not found within ' + timeout + 'ms');
};

const dumpView = () => {
  const root = document.querySelector('div.layout') || document.body;
  const desc = (el) => el.tagName.toLowerCase() + (el.id ? '#' + el.id : '') + (typeof el.className === 'string' && el.className.trim() ? '.' + el.className.trim().split(/\s+/).join('.') : '');
  const walk = (el, depth) => {
    if (depth > 3) return '';
    let out = '  '.repeat(depth) + desc(el) + '\n';
    for (const c of el.children) out += walk(c, depth + 1);
    return out;
  };
  return walk(root, 0).slice(0, 500);
};

const safeUrl = (u) => (typeof u === 'string' && /^https?:\/\//i.test(u)) ? u : null;
const fmtDate = (v) => {
  if (!v) return '';
  const d = new Date(v);
  return isNaN(d.getTime()) ? '' : d.toLocaleDateString();
};

let msgEl = null;
try {
  // Idempotency: replace any previous instance
  const old = document.getElementById(ROOT_ID);
  if (old) old.remove();

  const host = document.createElement('div');
  host.id = ROOT_ID;

  let sidebar = null;
  try {
    sidebar = await waitForEl(
      () => document.querySelector('#watchlist-sidebar') || document.querySelector('aside[role="complementary"]'),
      8000,
      'watchlist sidebar'
    );
  } catch (e) {
    WidgetAI.log(e.message + ' - using floating dock instead', 'warn');
    WidgetAI.log('View structure: ' + dumpView(), 'warn');
  }

  if (sidebar) {
    sidebar.appendChild(host);
  } else {
    host.style.cssText = 'position:fixed;right:16px;bottom:16px;z-index:2147483647;width:300px;max-height:70vh;overflow:auto;';
    document.body.appendChild(host);
  }

  const shadow = host.attachShadow({ mode: 'open' });
  shadow.innerHTML = `
    <style>
      :host { all: initial; display: block; margin-top: 16px; font-family: system-ui, sans-serif; }
      .card { background: #fff; color: #222; border: 1px solid #ddd; border-radius: 8px; padding: 12px; box-shadow: 0 1px 3px rgba(0,0,0,.06); }
      .hd { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; }
      h3 { margin: 0; font-size: 15px; flex: 1; }
      .count { font-size: 12px; background: #eef; color: #335; border-radius: 10px; padding: 1px 8px; }
      .count:empty { display: none; }
      button { border: 1px solid #ccc; background: #f7f7f7; border-radius: 4px; cursor: pointer; font-size: 13px; padding: 2px 8px; }
      button:hover { background: #eee; }
      .msg { font-size: 13px; color: #666; }
      .msg.err { color: #b00020; }
      .msg:empty { display: none; }
      ul { list-style: none; margin: 0; padding: 0; }
      li { padding: 8px 0; border-top: 1px solid #f0f0f0; }
      li:first-child { border-top: none; }
      .title { font-weight: 600; font-size: 14px; color: #1a4fa0; text-decoration: none; }
      a.title:hover { text-decoration: underline; }
      span.title { color: #222; }
      .meta { font-size: 12px; color: #777; margin-top: 2px; }
      .note { font-size: 12px; color: #444; margin-top: 4px; font-style: italic; white-space: pre-wrap; }
    </style>
    <section class="card" aria-label="Saved movies">
      <div class="hd">
        <h3>Saved movies</h3>
        <span class="count"></span>
        <button class="refresh" type="button" title="Refresh list">Refresh</button>
      </div>
      <div class="msg"></div>
      <ul class="list"></ul>
    </section>`;

  msgEl = shadow.querySelector('.msg');
  const listEl = shadow.querySelector('.list');
  const countEl = shadow.querySelector('.count');
  const refreshBtn = shadow.querySelector('.refresh');

  const render = async () => {
    msgEl.className = 'msg';
    msgEl.textContent = 'Loading...';
    listEl.replaceChildren();
    countEl.textContent = '';

    const docs = await WidgetAI.db.list('saved_movies', { limit: 200 });
    if (!Array.isArray(docs) || docs.length === 0) {
      msgEl.textContent = 'No saved movies yet.';
      return { expected: 0, rendered: 0 };
    }

    msgEl.textContent = '';
    countEl.textContent = String(docs.length);

    for (const doc of docs) {
      const d = (doc && typeof doc.data === 'object' && doc.data) ? doc.data : {};
      const li = document.createElement('li');

      const rawTitle = d.title ?? d.name ?? d.movieTitle ?? 'Untitled';
      const title = String(rawTitle);
      const url = safeUrl(d.url);
      let titleEl;
      if (url) {
        titleEl = document.createElement('a');
        titleEl.href = url;
        titleEl.target = '_blank';
        titleEl.rel = 'noopener noreferrer';
      } else {
        titleEl = document.createElement('span');
      }
      titleEl.className = 'title';
      titleEl.textContent = title;
      li.appendChild(titleEl);

      const metaParts = [];
      if (d.year != null && d.year !== '') metaParts.push(String(d.year));
      if (d.rating != null && d.rating !== '') metaParts.push('Rating: ' + String(d.rating));
      const saved = fmtDate(d.savedAt || doc.createdAt);
      if (saved) metaParts.push('Saved ' + saved);
      if (metaParts.length) {
        const meta = document.createElement('div');
        meta.className = 'meta';
        meta.textContent = metaParts.join(' \u00b7 ');
        li.appendChild(meta);
      }

      if (d.note != null && String(d.note).trim()) {
        const note = document.createElement('div');
        note.className = 'note';
        note.textContent = String(d.note).slice(0, 300);
        li.appendChild(note);
      }

      listEl.appendChild(li);
    }
    return { expected: docs.length, rendered: listEl.querySelectorAll('li').length };
  };

  refreshBtn.addEventListener('click', async () => {
    refreshBtn.disabled = true;
    try {
      const r = await render();
      WidgetAI.log('Refreshed: ' + r.rendered + ' saved movie(s) shown');
    } catch (err) {
      msgEl.className = 'msg err';
      msgEl.textContent = 'Could not load saved movies: ' + err.message;
      WidgetAI.log('Refresh failed: ' + err.message, 'error');
    } finally {
      refreshBtn.disabled = false;
    }
  });

  WidgetAI.log('Loading saved movies from your data store...');
  const result = await render();

  if (!host.isConnected) throw new Error('Widget container was removed from the page');
  if (result.rendered !== result.expected) {
    throw new Error('Rendered ' + result.rendered + ' of ' + result.expected + ' saved movies');
  }

  const where = sidebar ? 'sidebar' : 'floating dock';
  WidgetAI.log('Showing ' + result.rendered + ' saved movie(s) in the ' + where);
  WidgetAI.status('completed', result.rendered ? ('Showing ' + result.rendered + ' saved movie(s)') : 'No saved movies yet');
} catch (err) {
  WidgetAI.log('Error: ' + err.message, 'error');
  if (msgEl) {
    msgEl.className = 'msg err';
    msgEl.textContent = 'Could not load saved movies: ' + err.message;
  }
  WidgetAI.status('failed', err.message);
}
